INSERT INTO public.applications VALUES ('6e0d3248-8937-4312-929d-8aa17ff6ba0b', '2f7e5380-0785-4e00-bef7-a1c3c2dc9a34', '43f698b8-ba4f-4650-a50a-2c34aa939877', 82.5, '{"overall_score": 82.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 90.0, "explanation": "\u1ee8ng vi\u00ean \u0111\u00e1p \u1ee9ng \u0111\u1ea7y \u0111\u1ee7 c\u00e1c k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt c\u1ed1t l\u00f5i \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u: Python, FastAPI, PostgreSQL v\u00e0 Docker."}, {"name": "experience_years", "weight": 0.3, "score": 100.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 4 n\u0103m kinh nghi\u1ec7m, v\u01b0\u1ee3t m\u1ee9c y\u00eau c\u1ea7u t\u1ed1i thi\u1ec3u l\u00e0 3 n\u0103m."}, {"name": "education", "weight": 0.15, "score": 80.0, "explanation": "T\u1ed1t nghi\u1ec7p \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa, m\u1ed9t trong nh\u1eefng tr\u01b0\u1eddng \u0111\u00e0o t\u1ea1o k\u1ef9 thu\u1eadt uy t\u00edn nh\u1ea5t t\u1ea1i Vi\u1ec7t Nam."}, {"name": "domain_knowledge", "weight": 0.15, "score": 40.0, "explanation": "CV ch\u01b0a \u0111\u1ec1 c\u1eadp \u0111\u1ebfn kinh nghi\u1ec7m v\u1ec1 AI Agents, LLM pipelines ho\u1eb7c LangChain/RAG - nh\u1eefng y\u00eau c\u1ea7u chuy\u00ean bi\u1ec7t cho v\u1ecb tr\u00ed n\u00e0y."}], "strengths": ["Kinh nghi\u1ec7m l\u00e0m vi\u1ec7c th\u1ef1c t\u1ebf (4 n\u0103m) v\u01b0\u1ee3t y\u00eau c\u1ea7u t\u1ed1i thi\u1ec3u.", "N\u1ec1n t\u1ea3ng k\u1ef9 thu\u1eadt v\u1eefng ch\u1eafc v\u1edbi c\u00e1c c\u00f4ng ngh\u1ec7 y\u00eau c\u1ea7u (Python, FastAPI, Docker, PostgreSQL).", "N\u1ec1n t\u1ea3ng h\u1ecdc v\u1ea5n t\u1ed1t (\u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa)."], "gaps": ["Thi\u1ebfu b\u1eb1ng ch\u1ee9ng v\u1ec1 kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1edbi AI Agents v\u00e0 LLM pipelines.", "Kh\u00f4ng \u0111\u1ec1 c\u1eadp \u0111\u1ebfn ki\u1ebfn th\u1ee9c ho\u1eb7c d\u1ef1 \u00e1n s\u1eed d\u1ee5ng LangChain/RAG (l\u1ee3i th\u1ebf l\u1edbn trong JD).", "Th\u00f4ng tin trong CV kh\u00e1 s\u01a1 s\u00e0i, ch\u01b0a th\u1ec3 hi\u1ec7n \u0111\u01b0\u1ee3c c\u00e1c d\u1ef1 \u00e1n c\u1ee5 th\u1ec3 ho\u1eb7c quy m\u00f4 h\u1ec7 th\u1ed1ng \u0111\u00e3 t\u1eebng tham gia."], "recommendation": "N\u00ean m\u1eddi ph\u1ecfng v\u1ea5n v\u00f2ng s\u01a1 lo\u1ea1i (Screening). M\u1eb7c d\u00f9 \u1ee9ng vi\u00ean \u0111\u00e1p \u1ee9ng t\u1ed1t v\u1ec1 k\u1ef9 n\u0103ng n\u1ec1n t\u1ea3ng (Backend/Infrastructure), c\u1ea7n l\u00e0m r\u00f5 kh\u1ea3 n\u0103ng l\u00e0m vi\u1ec7c v\u1edbi AI/LLM trong bu\u1ed5i ph\u1ecfng v\u1ea5n \u0111\u1ec3 x\u00e1c \u0111\u1ecbnh xem \u1ee9ng vi\u00ean c\u00f3 kh\u1ea3 n\u0103ng h\u1ecdc h\u1ecfi nhanh ho\u1eb7c \u0111\u00e3 t\u1eebng l\u00e0m d\u1ef1 \u00e1n AI nh\u01b0ng ch\u01b0a li\u1ec7t k\u00ea chi ti\u1ebft hay kh\u00f4ng."}', 'new', NULL, NULL, '2026-09-26 21:48:24.071136+07', '2026-09-26 21:48:27.109115+07') ON CONFLICT DO NOTHING;
