INSERT INTO public.applications VALUES ('c728365b-1ac9-48d3-aa2f-7f54a2cf7220', 'd6a08906-f9e6-41fd-8e8c-b4aafce6aee5', 'fee5df20-a93f-4f44-97c0-1d04e4ef24ba', 40, '{"overall_score": 40.0, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 100.0, "explanation": "\u1ee8ng vi\u00ean \u0111\u00e1p \u1ee9ng ch\u00ednh x\u00e1c c\u00e1c k\u1ef9 n\u0103ng c\u1ed1t l\u00f5i \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u l\u00e0 Python v\u00e0 FastAPI."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "CV kh\u00f4ng cung c\u1ea5p th\u00f4ng tin v\u1ec1 s\u1ed1 n\u0103m kinh nghi\u1ec7m l\u00e0m vi\u1ec7c, kh\u00f4ng th\u1ec3 x\u00e1c \u0111\u1ecbnh kh\u1ea3 n\u0103ng \u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u c\u1ea5p b\u1eadc ''Lead''."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p ho\u1eb7c ch\u1ee9ng ch\u1ec9 chuy\u00ean m\u00f4n trong CV."}, {"name": "domain_knowledge", "weight": 0.15, "score": 0.0, "explanation": "CV kh\u00f4ng \u0111\u1ec1 c\u1eadp \u0111\u1ebfn c\u00e1c d\u1ef1 \u00e1n AI c\u1ee5 th\u1ec3, ki\u1ebfn th\u1ee9c v\u1ec1 Machine Learning, Deep Learning hay c\u00e1c framework AI li\u00ean quan ngo\u00e0i k\u1ef9 n\u0103ng l\u1eadp tr\u00ecnh c\u01a1 b\u1ea3n."}], "strengths": ["S\u1edf h\u1eefu k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt n\u1ec1n t\u1ea3ng ph\u00f9 h\u1ee3p v\u1edbi y\u00eau c\u1ea7u c\u00f4ng vi\u1ec7c (Python, FastAPI)."], "gaps": ["Thi\u1ebfu th\u00f4ng tin v\u1ec1 s\u1ed1 n\u0103m kinh nghi\u1ec7m (\u0111\u1eb7c bi\u1ec7t quan tr\u1ecdng cho v\u1ecb tr\u00ed Lead).", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 tr\u00ecnh \u0111\u1ed9 h\u1ecdc v\u1ea5n.", "Thi\u1ebfu b\u1eb1ng ch\u1ee9ng v\u1ec1 kinh nghi\u1ec7m th\u1ef1c t\u1ebf trong l\u0129nh v\u1ef1c AI (c\u00e1c d\u1ef1 \u00e1n \u0111\u00e3 th\u1ef1c hi\u1ec7n, m\u00f4 h\u00ecnh \u0111\u00e3 tri\u1ec3n khai).", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 k\u1ef9 n\u0103ng l\u00e3nh \u0111\u1ea1o ho\u1eb7c qu\u1ea3n l\u00fd \u0111\u1ed9i nh\u00f3m (y\u00eau c\u1ea7u b\u1eaft bu\u1ed9c cho v\u1ecb tr\u00ed Lead)."], "recommendation": "Kh\u00f4ng n\u00ean m\u1eddi ph\u1ecfng v\u1ea5n ngay. C\u1ea7n y\u00eau c\u1ea7u \u1ee9ng vi\u00ean b\u1ed5 sung CV chi ti\u1ebft h\u01a1n (\u0111\u1eb7c bi\u1ec7t l\u00e0 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c trong l\u0129nh v\u1ef1c AI v\u00e0 c\u00e1c d\u1ef1 \u00e1n \u0111\u00e3 d\u1eabn d\u1eaft) tr\u01b0\u1edbc khi \u0111\u01b0a ra quy\u1ebft \u0111\u1ecbnh ti\u1ebfp theo."}', 'new', NULL, NULL, '2026-09-26 21:54:04.307639+07', '2026-09-26 21:54:08.860013+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('23474d44-b195-4f6d-9451-a535435836cc', 'd6a08906-f9e6-41fd-8e8c-b4aafce6aee5', '587d9c59-74ab-482e-b2e1-b71595512118', 88.5, '{"overall_score": 88.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 95.0, "explanation": "\u1ee8ng vi\u00ean th\u1ec3 hi\u1ec7n s\u1ef1 th\u00e0nh th\u1ea1o v\u01b0\u1ee3t tr\u1ed9i v\u1edbi Python v\u00e0 FastAPI th\u00f4ng qua kinh nghi\u1ec7m th\u1ef1c t\u1ebf t\u1ea1i Tech Corp v\u00e0 c\u00e1c d\u1ef1 \u00e1n AI. K\u1ef9 n\u0103ng b\u1ed5 tr\u1ee3 (LangChain, RAG, Docker) r\u1ea5t ph\u00f9 h\u1ee3p v\u1edbi y\u00eau c\u1ea7u ph\u00e1t tri\u1ec3n AI hi\u1ec7n \u0111\u1ea1i."}, {"name": "experience_years", "weight": 0.3, "score": 80.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 h\u01a1n 4 n\u0103m kinh nghi\u1ec7m. M\u1eb7c d\u00f9 \u0111\u00e3 \u0111\u1ea3m nh\u1eadn v\u1ecb tr\u00ed Senior, nh\u01b0ng \u0111\u1ec3 \u0111\u1ea1t m\u1ee9c ''Lead'' th\u1ef1c th\u1ee5, \u1ee9ng vi\u00ean c\u1ea7n th\u00eam th\u1eddi gian \u0111\u1ec3 ch\u1ee9ng minh kh\u1ea3 n\u0103ng qu\u1ea3n l\u00fd \u0111\u1ed9i ng\u0169 ho\u1eb7c d\u1eabn d\u1eaft d\u1ef1 \u00e1n quy m\u00f4 l\u1edbn h\u01a1n."}, {"name": "education", "weight": 0.15, "score": 95.0, "explanation": "T\u1ed1t nghi\u1ec7p K\u1ef9 s\u01b0 CNTT t\u1ea1i \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa v\u1edbi GPA 3.6/4.0 (Xu\u1ea5t s\u1eafc) l\u00e0 n\u1ec1n t\u1ea3ng h\u1ecdc thu\u1eadt r\u1ea5t v\u1eefng ch\u1eafc cho v\u1ecb tr\u00ed k\u1ef9 thu\u1eadt c\u1ea5p cao."}, {"name": "domain_knowledge", "weight": 0.15, "score": 85.0, "explanation": "C\u00f3 ki\u1ebfn th\u1ee9c chuy\u00ean s\u00e2u v\u1ec1 LLM, RAG v\u00e0 t\u00edch h\u1ee3p API AI. Kinh nghi\u1ec7m th\u1ef1c t\u1ebf trong vi\u1ec7c x\u00e2y d\u1ef1ng h\u1ec7 th\u1ed1ng AI Recruiting Platform cho th\u1ea5y s\u1ef1 hi\u1ec3u bi\u1ebft t\u1ed1t v\u1ec1 \u1ee9ng d\u1ee5ng AI trong th\u1ef1c t\u1ebf."}], "strengths": ["N\u1ec1n t\u1ea3ng k\u1ef9 thu\u1eadt v\u1eefng ch\u1eafc t\u1eeb \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa v\u1edbi th\u00e0nh t\u00edch h\u1ecdc t\u1eadp xu\u1ea5t s\u1eafc.", "Kinh nghi\u1ec7m th\u1ef1c chi\u1ebfn v\u1edbi c\u00e1c c\u00f4ng ngh\u1ec7 AI hi\u1ec7n \u0111\u1ea1i (LLM, RAG, LangChain, Gemini API).", "C\u00f3 t\u01b0 duy h\u1ec7 th\u1ed1ng t\u1ed1t, th\u1ec3 hi\u1ec7n qua vi\u1ec7c thi\u1ebft k\u1ebf ki\u1ebfn tr\u00fac microservices v\u1edbi FastAPI v\u00e0 Celery.", "S\u1edf h\u1eefu c\u00e1c k\u1ef9 n\u0103ng b\u1ed5 tr\u1ee3 quan tr\u1ecdng nh\u01b0 Docker, CI/CD, PostgreSQL gi\u00fap t\u1ed1i \u01b0u h\u00f3a quy tr\u00ecnh tri\u1ec3n khai AI."], "gaps": ["Thi\u1ebfu th\u00f4ng tin c\u1ee5 th\u1ec3 v\u1ec1 kinh nghi\u1ec7m qu\u1ea3n l\u00fd nh\u00e2n s\u1ef1 ho\u1eb7c d\u1eabn d\u1eaft \u0111\u1ed9i ng\u0169 (Team Lead/Mentoring) - y\u1ebfu t\u1ed1 quan tr\u1ecdng cho v\u1ecb tr\u00ed ''Lead''.", "Ch\u01b0a c\u00f3 b\u1eb1ng ch\u1ee9ng r\u00f5 r\u00e0ng v\u1ec1 kh\u1ea3 n\u0103ng t\u1ed1i \u01b0u h\u00f3a chi ph\u00ed v\u1eadn h\u00e0nh (Cost Optimization) cho c\u00e1c h\u1ec7 th\u1ed1ng AI quy m\u00f4 l\u1edbn."], "recommendation": "R\u1ea5t khuy\u1ebfn kh\u00edch m\u1eddi ph\u1ecfng v\u1ea5n. \u1ee8ng vi\u00ean c\u00f3 n\u0103ng l\u1ef1c k\u1ef9 thu\u1eadt xu\u1ea5t s\u1eafc v\u00e0 ph\u00f9 h\u1ee3p cao v\u1edbi y\u00eau c\u1ea7u c\u00f4ng vi\u1ec7c. Trong bu\u1ed5i ph\u1ecfng v\u1ea5n, HR n\u00ean t\u1eadp trung khai th\u00e1c kh\u1ea3 n\u0103ng l\u00e3nh \u0111\u1ea1o, t\u01b0 duy chi\u1ebfn l\u01b0\u1ee3c v\u00e0 kinh nghi\u1ec7m gi\u1ea3i quy\u1ebft c\u00e1c b\u00e0i to\u00e1n kh\u00f3 v\u1ec1 hi\u1ec7u n\u0103ng h\u1ec7 th\u1ed1ng \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 kh\u1ea3 n\u0103ng \u0111\u1ea3m nh\u1eadn vai tr\u00f2 Lead."}', 'new', NULL, NULL, '2026-09-26 22:08:24.426653+07', '2026-09-26 22:08:33.021758+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('e941e7bf-a41b-4ddf-a88f-5a9e53e2ff12', 'd6a08906-f9e6-41fd-8e8c-b4aafce6aee5', '61900d0e-2bda-40a6-926f-3d3e50a22f06', 35.5, '{"overall_score": 35.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 40.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 k\u1ef9 n\u0103ng Python nh\u01b0ng kinh nghi\u1ec7m ch\u1ee7 y\u1ebfu l\u00e0 Django (Web framework), thi\u1ebfu kinh nghi\u1ec7m chuy\u00ean s\u00e2u v\u1ec1 FastAPI v\u00e0 c\u00e1c k\u1ef9 n\u0103ng c\u1ed1t l\u00f5i c\u1ee7a AI Engineer (Machine Learning, Deep Learning, NLP, Computer Vision)."}, {"name": "experience_years", "weight": 0.3, "score": 10.0, "explanation": "\u1ee8ng vi\u00ean l\u00e0 sinh vi\u00ean m\u1edbi t\u1ed1t nghi\u1ec7p (Fresher), ch\u01b0a c\u00f3 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c th\u1ef1c t\u1ebf \u1edf v\u1ecb tr\u00ed AI Engineer ho\u1eb7c c\u00e1c d\u1ef1 \u00e1n AI chuy\u00ean s\u00e2u. V\u1ecb tr\u00ed Lead AI Engineer y\u00eau c\u1ea7u kinh nghi\u1ec7m d\u00e0y d\u1ea1n."}, {"name": "education", "weight": 0.15, "score": 60.0, "explanation": "T\u1ed1t nghi\u1ec7p chuy\u00ean ng\u00e0nh K\u1ef9 thu\u1eadt ph\u1ea7n m\u1ec1m t\u1ea1i \u0110\u1ea1i h\u1ecdc S\u00e0i G\u00f2n, n\u1ec1n t\u1ea3ng h\u1ecdc thu\u1eadt ph\u00f9 h\u1ee3p v\u1edbi ng\u00e0nh CNTT nh\u01b0ng ch\u01b0a c\u00f3 b\u1eb1ng c\u1ea5p chuy\u00ean s\u00e2u v\u1ec1 AI/Data Science."}, {"name": "domain_knowledge", "weight": 0.15, "score": 20.0, "explanation": "\u1ee8ng vi\u00ean t\u1eadp trung v\u00e0o m\u1ea3ng Embedded v\u00e0 Web Development, ch\u01b0a c\u00f3 ki\u1ebfn th\u1ee9c chuy\u00ean m\u00f4n v\u1ec1 l\u0129nh v\u1ef1c AI/ML."}], "strengths": ["N\u1ec1n t\u1ea3ng l\u1eadp tr\u00ecnh t\u1ed1t v\u1edbi C/C++, Python, Java.", "C\u00f3 kinh nghi\u1ec7m th\u1ef1c hi\u1ec7n c\u00e1c d\u1ef1 \u00e1n full-stack (React, Spring Boot, MySQL).", "K\u1ef9 n\u0103ng ph\u00e2n t\u00edch y\u00eau c\u1ea7u, debug v\u00e0 s\u1eed d\u1ee5ng c\u00e1c c\u00f4ng c\u1ee5 qu\u1ea3n l\u00fd d\u1ef1 \u00e1n (Jira, Git) t\u1ed1t.", "Kh\u1ea3 n\u0103ng giao ti\u1ebfp ti\u1ebfng Anh kh\u00e1 (VSTEP 5.5)."], "gaps": ["Thi\u1ebfu ho\u00e0n to\u00e0n kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1ec1 AI/Machine Learning (kh\u00f4ng c\u00f3 d\u1ef1 \u00e1n AI trong CV).", "Thi\u1ebfu kinh nghi\u1ec7m v\u1edbi FastAPI (y\u00eau c\u1ea7u b\u1eaft bu\u1ed9c c\u1ee7a JD).", "Ch\u01b0a c\u00f3 kinh nghi\u1ec7m l\u00e3nh \u0111\u1ea1o (Lead) ho\u1eb7c qu\u1ea3n l\u00fd d\u1ef1 \u00e1n AI.", "\u0110\u1ecbnh h\u01b0\u1edbng ngh\u1ec1 nghi\u1ec7p hi\u1ec7n t\u1ea1i c\u1ee7a \u1ee9ng vi\u00ean l\u00e0 Embedded Software v\u00e0 Automotive, kh\u00f4ng kh\u1edbp v\u1edbi v\u1ecb tr\u00ed AI Engineer."], "recommendation": "KH\u00d4NG PH\u00d9 H\u1ee2P. \u1ee8ng vi\u00ean hi\u1ec7n t\u1ea1i l\u00e0 Fresher v\u1edbi \u0111\u1ecbnh h\u01b0\u1edbng Embedded/Web, ho\u00e0n to\u00e0n kh\u00f4ng \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u v\u1ec1 tr\u00ecnh \u0111\u1ed9 chuy\u00ean m\u00f4n v\u00e0 kinh nghi\u1ec7m cho v\u1ecb tr\u00ed Lead AI Engineer. Khuy\u1ebfn ngh\u1ecb kh\u00f4ng m\u1eddi ph\u1ecfng v\u1ea5n cho v\u1ecb tr\u00ed n\u00e0y, c\u00f3 th\u1ec3 l\u01b0u h\u1ed3 s\u01a1 cho c\u00e1c v\u1ecb tr\u00ed Fresher Backend ho\u1eb7c Embedded n\u1ebfu c\u00f4ng ty c\u00f3 nhu c\u1ea7u."}', 'new', NULL, NULL, '2026-09-26 22:12:20.950579+07', '2026-09-26 22:12:36.042323+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('816738ee-d6ae-4374-849b-7ee853f565f8', 'd6a08906-f9e6-41fd-8e8c-b4aafce6aee5', 'a90c3cca-ac89-42a2-af37-83409bfb8a9a', 94.5, '{"overall_score": 94.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 100.0, "explanation": "\u1ee8ng vi\u00ean th\u1ec3 hi\u1ec7n tr\u00ecnh \u0111\u1ed9 Senior v\u1ec1 Python v\u00e0 c\u00f3 kinh nghi\u1ec7m th\u1ef1c chi\u1ebfn v\u1edbi FastAPI qua d\u1ef1 \u00e1n t\u1ea1i VNG Corporation, \u0111\u00e1p \u1ee9ng ho\u00e0n h\u1ea3o y\u00eau c\u1ea7u k\u1ef9 thu\u1eadt c\u1ed1t l\u00f5i."}, {"name": "experience_years", "weight": 0.3, "score": 95.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 h\u01a1n 5 n\u0103m kinh nghi\u1ec7m chuy\u00ean s\u00e2u trong l\u0129nh v\u1ef1c AI v\u00e0 Backend, ph\u00f9 h\u1ee3p v\u1edbi y\u00eau c\u1ea7u v\u1ecb tr\u00ed Lead AI Engineer."}, {"name": "education", "weight": 0.15, "score": 90.0, "explanation": "S\u1edf h\u1eefu b\u1eb1ng Th\u1ea1c s\u0129 Khoa h\u1ecdc M\u00e1y t\u00ednh t\u1eeb \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa H\u00e0 N\u1ed9i, n\u1ec1n t\u1ea3ng h\u1ecdc thu\u1eadt r\u1ea5t v\u1eefng ch\u1eafc."}, {"name": "domain_knowledge", "weight": 0.15, "score": 90.0, "explanation": "C\u00f3 ki\u1ebfn th\u1ee9c chuy\u00ean s\u00e2u v\u1ec1 Generative AI, RAG, LLM v\u00e0 t\u1ed1i \u01b0u h\u00f3a h\u1ec7 th\u1ed1ng, v\u01b0\u1ee3t xa y\u00eau c\u1ea7u c\u01a1 b\u1ea3n c\u1ee7a JD."}], "strengths": ["Kinh nghi\u1ec7m l\u00e3nh \u0111\u1ea1o nh\u00f3m (Lead 8 k\u1ef9 s\u01b0) v\u00e0 qu\u1ea3n l\u00fd d\u1ef1 \u00e1n quy m\u00f4 l\u1edbn.", "S\u1edf h\u1eefu k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt chuy\u00ean s\u00e2u: RAG, Fine-tuning LLM, Inference Optimization.", "C\u00f3 kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1edbi c\u00e1c c\u00f4ng ngh\u1ec7 hi\u1ec7n \u0111\u1ea1i (vLLM, Qdrant, Milvus, AWS).", "N\u1ec1n t\u1ea3ng h\u1ecdc v\u1ea5n xu\u1ea5t s\u1eafc (GPA 3.7/4.0, Th\u1ea1c s\u0129 CNTT)."], "gaps": ["JD hi\u1ec7n t\u1ea1i kh\u00e1 s\u01a1 s\u00e0i (ch\u1ec9 ghi ''Develop AI''), do \u0111\u00f3 kh\u00f3 x\u00e1c \u0111\u1ecbnh c\u00e1c kho\u1ea3ng tr\u1ed1ng k\u1ef9 thu\u1eadt c\u1ee5 th\u1ec3 so v\u1edbi nhu c\u1ea7u th\u1ef1c t\u1ebf c\u1ee7a c\u00f4ng ty. C\u1ea7n l\u00e0m r\u00f5 th\u00eam v\u1ec1 stack c\u00f4ng ngh\u1ec7 \u0111\u1eb7c th\u00f9 n\u1ebfu c\u00f3 ngo\u00e0i Python/FastAPI."], "recommendation": "\u0110\u1eb7c bi\u1ec7t khuy\u1ebfn ngh\u1ecb ph\u1ecfng v\u1ea5n ngay. \u1ee8ng vi\u00ean l\u00e0 m\u1ed9t nh\u00e2n s\u1ef1 c\u1ea5p cao (Senior/Lead) c\u00f3 n\u0103ng l\u1ef1c v\u01b0\u1ee3t tr\u1ed9i so v\u1edbi y\u00eau c\u1ea7u t\u1ed1i thi\u1ec3u c\u1ee7a JD. Trong bu\u1ed5i ph\u1ecfng v\u1ea5n, n\u00ean t\u1eadp trung v\u00e0o t\u01b0 duy ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng v\u00e0 kh\u1ea3 n\u0103ng gi\u1ea3i quy\u1ebft c\u00e1c b\u00e0i to\u00e1n AI ph\u1ee9c t\u1ea1p \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 m\u1ee9c \u0111\u1ed9 ph\u00f9 h\u1ee3p v\u1edbi v\u0103n h\u00f3a v\u00e0 \u0111\u1ecbnh h\u01b0\u1edbng chi\u1ebfn l\u01b0\u1ee3c c\u1ee7a c\u00f4ng ty."}', 'new', NULL, NULL, '2026-09-26 22:16:29.933608+07', '2026-09-26 22:16:34.513619+07') ON CONFLICT DO NOTHING;
