INSERT INTO public.applications VALUES ('9b55d346-9dcb-4502-b3f5-0f7aaca45d13', '85a3816d-a078-49ba-82ac-0318738eab7c', '9d28619c-fdd8-4192-a7c1-b05487360e51', 42.5, '{"overall_score": 42.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 50.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 kinh nghi\u1ec7m v\u1edbi Python (\u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u), nh\u01b0ng thi\u1ebfu b\u1eb1ng ch\u1ee9ng v\u1ec1 vi\u1ec7c s\u1eed d\u1ee5ng Gemini API v\u00e0 ki\u1ebfn tr\u00fac Microservices trong CV."}, {"name": "experience_years", "weight": 0.3, "score": 30.0, "explanation": "V\u1ecb tr\u00ed Senior AI Architect th\u01b0\u1eddng y\u00eau c\u1ea7u t\u1eeb 5-7 n\u0103m kinh nghi\u1ec7m tr\u1edf l\u00ean. \u1ee8ng vi\u00ean ch\u1ec9 c\u00f3 3 n\u0103m kinh nghi\u1ec7m, ch\u01b0a \u0111\u1ea1t chu\u1ea9n Senior."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "Th\u00f4ng tin v\u1ec1 tr\u00ecnh \u0111\u1ed9 h\u1ecdc v\u1ea5n kh\u00f4ng \u0111\u01b0\u1ee3c cung c\u1ea5p trong CV."}, {"name": "domain_knowledge", "weight": 0.15, "score": 20.0, "explanation": "Thi\u1ebfu th\u00f4ng tin v\u1ec1 kinh nghi\u1ec7m tri\u1ec3n khai c\u00e1c h\u1ec7 th\u1ed1ng AI Enterprise ho\u1eb7c c\u00e1c d\u1ef1 \u00e1n li\u00ean quan \u0111\u1ebfn AI/LLM."}], "strengths": ["C\u00f3 n\u1ec1n t\u1ea3ng k\u1ef9 thu\u1eadt v\u1eefng ch\u1eafc v\u1edbi Python.", "C\u00f3 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c v\u1edbi Docker, h\u1ed7 tr\u1ee3 t\u1ed1t cho vi\u1ec7c tri\u1ec3n khai h\u1ec7 th\u1ed1ng."], "gaps": ["Thi\u1ebfu kinh nghi\u1ec7m chuy\u00ean s\u00e2u v\u1ec1 AI/LLM (\u0111\u1eb7c bi\u1ec7t l\u00e0 Gemini API).", "Ch\u01b0a c\u00f3 kinh nghi\u1ec7m thi\u1ebft k\u1ebf ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng \u1edf quy m\u00f4 Enterprise.", "S\u1ed1 n\u0103m kinh nghi\u1ec7m ch\u01b0a \u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u cho c\u1ea5p b\u1eadc Senior.", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p chuy\u00ean m\u00f4n."], "recommendation": "Kh\u00f4ng n\u00ean m\u1eddi ph\u1ecfng v\u1ea5n cho v\u1ecb tr\u00ed Senior AI Architect. \u1ee8ng vi\u00ean hi\u1ec7n t\u1ea1i ph\u00f9 h\u1ee3p h\u01a1n v\u1edbi c\u00e1c v\u1ecb tr\u00ed Junior/Mid-level Backend Developer. N\u1ebfu c\u00f4ng ty c\u00f3 nhu c\u1ea7u \u0111\u00e0o t\u1ea1o n\u1ed9i b\u1ed9, c\u00f3 th\u1ec3 c\u00e2n nh\u1eafc ph\u1ecfng v\u1ea5n \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 ti\u1ec1m n\u0103ng, nh\u01b0ng kh\u00f4ng \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u c\u00f4ng vi\u1ec7c hi\u1ec7n t\u1ea1i."}', 'new', NULL, NULL, '2026-09-27 09:06:50.682949+07', '2026-09-27 09:06:53.215584+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('8a7d3119-cef8-441a-a594-d4af0c8be3af', '85a3816d-a078-49ba-82ac-0318738eab7c', '07162fa5-6ad6-4a44-9773-79102560743a', 82.5, '{"overall_score": 82.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 90.0, "explanation": "\u1ee8ng vi\u00ean th\u00e0nh th\u1ea1o Python v\u00e0 c\u00f3 kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1edbi Gemini AI. Vi\u1ec7c s\u1eed d\u1ee5ng FastAPI v\u00e0 Docker cho th\u1ea5y kh\u1ea3 n\u0103ng l\u00e0m vi\u1ec7c t\u1ed1t v\u1edbi ki\u1ebfn tr\u00fac Microservices."}, {"name": "experience_years", "weight": 0.3, "score": 75.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 4 n\u0103m kinh nghi\u1ec7m. \u0110\u1ed1i v\u1edbi v\u1ecb tr\u00ed Senior AI Architect, m\u1ee9c \u0111\u1ed9 n\u00e0y \u1edf ng\u01b0\u1ee1ng t\u1ed1i thi\u1ec3u, c\u1ea7n \u0111\u00e1nh gi\u00e1 th\u00eam v\u1ec1 kh\u1ea3 n\u0103ng thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng quy m\u00f4 l\u1edbn (scalability)."}, {"name": "education", "weight": 0.15, "score": 95.0, "explanation": "B\u1eb1ng Th\u1ea1c s\u0129 Khoa h\u1ecdc M\u00e1y t\u00ednh t\u1eeb \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa l\u00e0 n\u1ec1n t\u1ea3ng h\u1ecdc thu\u1eadt r\u1ea5t m\u1ea1nh, ph\u00f9 h\u1ee3p v\u1edbi y\u00eau c\u1ea7u chuy\u00ean s\u00e2u c\u1ee7a v\u1ecb tr\u00ed Architect."}, {"name": "domain_knowledge", "weight": 0.15, "score": 70.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 kinh nghi\u1ec7m v\u1ec1 RAG (Retrieval-Augmented Generation), tuy nhi\u00ean ch\u01b0a th\u1ec3 hi\u1ec7n r\u00f5 kinh nghi\u1ec7m trong vi\u1ec7c x\u00e2y d\u1ef1ng ki\u1ebfn tr\u00fac AI \u1edf quy m\u00f4 Enterprise."}], "strengths": ["N\u1ec1n t\u1ea3ng h\u1ecdc v\u1ea5n chuy\u00ean m\u00f4n cao (Th\u1ea1c s\u0129 KHMT).", "K\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt th\u1ef1c t\u1ebf s\u00e1t v\u1edbi y\u00eau c\u1ea7u (Python, Gemini API, RAG).", "C\u00f3 kinh nghi\u1ec7m tri\u1ec3n khai h\u1ec7 th\u1ed1ng v\u1edbi Docker v\u00e0 FastAPI, ph\u00f9 h\u1ee3p v\u1edbi t\u01b0 duy Microservices."], "gaps": ["Thi\u1ebfu th\u00f4ng tin c\u1ee5 th\u1ec3 v\u1ec1 kinh nghi\u1ec7m thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng (System Design) \u1edf quy m\u00f4 Enterprise.", "S\u1ed1 n\u0103m kinh nghi\u1ec7m (4 n\u0103m) c\u00f3 th\u1ec3 l\u00e0 th\u00e1ch th\u1ee9c n\u1ebfu d\u1ef1 \u00e1n y\u00eau c\u1ea7u kh\u1ea3 n\u0103ng d\u1eabn d\u1eaft \u0111\u1ed9i ng\u0169 ho\u1eb7c qu\u1ea3n l\u00fd ki\u1ebfn tr\u00fac ph\u1ee9c t\u1ea1p l\u00e2u n\u0103m."], "recommendation": "N\u00ean m\u1eddi ph\u1ecfng v\u1ea5n. \u1ee8ng vi\u00ean c\u00f3 ti\u1ec1m n\u0103ng k\u1ef9 thu\u1eadt r\u1ea5t t\u1ed1t. Trong bu\u1ed5i ph\u1ecfng v\u1ea5n, c\u1ea7n t\u1eadp trung khai th\u00e1c s\u00e2u v\u00e0o c\u00e1c d\u1ef1 \u00e1n \u0111\u00e3 th\u1ef1c hi\u1ec7n \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 t\u01b0 duy ki\u1ebfn tr\u00fac (System Architecture) v\u00e0 kh\u1ea3 n\u0103ng gi\u1ea3i quy\u1ebft c\u00e1c b\u00e0i to\u00e1n kh\u00f3 trong m\u00f4i tr\u01b0\u1eddng doanh nghi\u1ec7p."}', 'interview_invited', NULL, NULL, '2026-09-27 09:06:47.444814+07', '2026-09-27 09:06:58.340163+07') ON CONFLICT DO NOTHING;
