INSERT INTO public.applications VALUES ('3242197b-2313-4cb7-8d43-b111e37cc117', '7e8e6e13-74e7-47bd-8716-281a2f478674', '50f0b8d4-6c22-4efa-bbef-6a50f427c11d', 0, '{"overall_score": 0.0, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u v\u1ec1 k\u1ef9 n\u0103ng Python ho\u1eb7c Docker trong h\u1ed3 s\u01a1 \u1ee9ng vi\u00ean."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 s\u1ed1 n\u0103m kinh nghi\u1ec7m l\u00e0m vi\u1ec7c."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 tr\u00ecnh \u0111\u1ed9 h\u1ecdc v\u1ea5n."}, {"name": "domain_knowledge", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 ki\u1ebfn th\u1ee9c chuy\u00ean m\u00f4n ho\u1eb7c d\u1ef1 \u00e1n li\u00ean quan \u0111\u1ebfn AI."}], "strengths": ["Kh\u00f4ng c\u00f3 \u0111i\u1ec3m m\u1ea1nh n\u00e0o \u0111\u01b0\u1ee3c x\u00e1c \u0111\u1ecbnh do thi\u1ebfu d\u1eef li\u1ec7u \u0111\u1ea7u v\u00e0o."], "gaps": ["Thi\u1ebfu ho\u00e0n to\u00e0n th\u00f4ng tin v\u1ec1 k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt (Python, Docker).", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 qu\u00e1 tr\u00ecnh l\u00e0m vi\u1ec7c v\u00e0 kinh nghi\u1ec7m th\u1ef1c t\u1ebf.", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p v\u00e0 chuy\u00ean m\u00f4n h\u1ecdc thu\u1eadt.", "Thi\u1ebfu th\u00f4ng tin li\u00ean h\u1ec7 v\u00e0 c\u00e1c d\u1ef1 \u00e1n \u0111\u00e3 th\u1ef1c hi\u1ec7n."], "recommendation": "T\u1eeb ch\u1ed1i ph\u1ecfng v\u1ea5n (Reject). H\u1ed3 s\u01a1 \u1ee9ng vi\u00ean hi\u1ec7n t\u1ea1i tr\u1ed1ng ho\u1eb7c kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u \u0111\u1ec3 \u0111\u00e1nh gi\u00e1. Vui l\u00f2ng y\u00eau c\u1ea7u \u1ee9ng vi\u00ean cung c\u1ea5p CV \u0111\u1ea7y \u0111\u1ee7 tr\u01b0\u1edbc khi th\u1ef1c hi\u1ec7n quy tr\u00ecnh s\u00e0ng l\u1ecdc ti\u1ebfp theo."}', 'new', NULL, NULL, '2026-09-27 09:08:25.012082+07', '2026-09-27 09:08:27.385543+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('63f217ca-f192-4177-b355-3c472f36ae2e', '59811686-ce42-46ce-9954-684635269880', '3f9f6ed3-9ff7-4f54-8dbe-0d0e2c56be05', 0, '{"overall_score": 0.0, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u CV \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 c\u00e1c k\u1ef9 n\u0103ng Python, Gemini API v\u00e0 Microservices."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 s\u1ed1 n\u0103m kinh nghi\u1ec7m l\u00e0m vi\u1ec7c trong CV."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p ho\u1eb7c tr\u00ecnh \u0111\u1ed9 h\u1ecdc v\u1ea5n trong CV."}, {"name": "domain_knowledge", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 ki\u1ebfn th\u1ee9c chuy\u00ean m\u00f4n ho\u1eb7c d\u1ef1 \u00e1n th\u1ef1c t\u1ebf li\u00ean quan \u0111\u1ebfn AI Enterprise."}], "strengths": ["Kh\u00f4ng th\u1ec3 x\u00e1c \u0111\u1ecbnh do thi\u1ebfu d\u1eef li\u1ec7u \u0111\u1ea7u v\u00e0o."], "gaps": ["Thi\u1ebfu to\u00e0n b\u1ed9 th\u00f4ng tin CV (K\u1ef9 n\u0103ng, Kinh nghi\u1ec7m, H\u1ecdc v\u1ea5n, D\u1ef1 \u00e1n)."], "recommendation": "T\u1eeb ch\u1ed1i ph\u1ecfng v\u1ea5n ho\u1eb7c y\u00eau c\u1ea7u \u1ee9ng vi\u00ean cung c\u1ea5p l\u1ea1i CV \u0111\u1ea7y \u0111\u1ee7. Hi\u1ec7n t\u1ea1i kh\u00f4ng c\u00f3 c\u01a1 s\u1edf d\u1eef li\u1ec7u \u0111\u1ec3 th\u1ef1c hi\u1ec7n \u0111\u00e1nh gi\u00e1 chuy\u00ean m\u00f4n cho v\u1ecb tr\u00ed Senior AI Architect."}', 'new', NULL, NULL, '2026-09-27 09:08:27.503218+07', '2026-09-27 09:08:29.666956+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('c60868d6-aaf5-4698-8c40-0b697a62c5d3', '59811686-ce42-46ce-9954-684635269880', 'f09d872e-d01e-4027-a0da-7f5e4e8ebdf1', 42.5, '{"overall_score": 42.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 50.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 k\u1ef9 n\u0103ng Python (\u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u), nh\u01b0ng thi\u1ebfu b\u1eb1ng ch\u1ee9ng v\u1ec1 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c v\u1edbi Gemini API v\u00e0 ki\u1ebfn tr\u00fac Microservices chuy\u00ean s\u00e2u cho h\u1ec7 th\u1ed1ng AI."}, {"name": "experience_years", "weight": 0.3, "score": 30.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 3 n\u0103m kinh nghi\u1ec7m. \u0110\u1ed1i v\u1edbi v\u1ecb tr\u00ed Senior AI Architect, y\u00eau c\u1ea7u th\u01b0\u1eddng t\u1eeb 5-7 n\u0103m tr\u1edf l\u00ean. M\u1ee9c \u0111\u1ed9 kinh nghi\u1ec7m hi\u1ec7n t\u1ea1i ch\u01b0a \u0111\u1ea1t chu\u1ea9n Senior."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "CV kh\u00f4ng cung c\u1ea5p th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p chuy\u00ean m\u00f4n."}, {"name": "domain_knowledge", "weight": 0.15, "score": 50.0, "explanation": "C\u00f3 kinh nghi\u1ec7m v\u1ec1 Docker (h\u1ed7 tr\u1ee3 tri\u1ec3n khai h\u1ec7 th\u1ed1ng), nh\u01b0ng ch\u01b0a th\u1ec3 hi\u1ec7n ki\u1ebfn th\u1ee9c chuy\u00ean s\u00e2u v\u1ec1 thi\u1ebft k\u1ebf ki\u1ebfn tr\u00fac AI Enterprise."}], "strengths": ["C\u00f3 n\u1ec1n t\u1ea3ng v\u1eefng ch\u1eafc v\u1ec1 ng\u00f4n ng\u1eef l\u1eadp tr\u00ecnh Python.", "C\u00f3 kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1edbi Docker, h\u1ed7 tr\u1ee3 t\u1ed1t cho vi\u1ec7c tri\u1ec3n khai h\u1ec7 th\u1ed1ng."], "gaps": ["Thi\u1ebfu kinh nghi\u1ec7m chuy\u00ean s\u00e2u v\u1ec1 ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng AI (AI Architect).", "Ch\u01b0a c\u00f3 b\u1eb1ng ch\u1ee9ng v\u1ec1 vi\u1ec7c s\u1eed d\u1ee5ng Gemini API ho\u1eb7c c\u00e1c m\u00f4 h\u00ecnh ng\u00f4n ng\u1eef l\u1edbn (LLMs).", "Thi\u1ebfu kinh nghi\u1ec7m v\u1ec1 thi\u1ebft k\u1ebf v\u00e0 v\u1eadn h\u00e0nh h\u1ec7 th\u1ed1ng Microservices ph\u1ee9c t\u1ea1p.", "S\u1ed1 n\u0103m kinh nghi\u1ec7m ch\u01b0a \u0111\u1ea1t y\u00eau c\u1ea7u cho c\u1ea5p b\u1eadc Senior."], "recommendation": "Kh\u00f4ng khuy\u1ebfn ngh\u1ecb ph\u1ecfng v\u1ea5n cho v\u1ecb tr\u00ed Senior AI Architect. \u1ee8ng vi\u00ean hi\u1ec7n t\u1ea1i ph\u00f9 h\u1ee3p h\u01a1n v\u1edbi c\u00e1c v\u1ecb tr\u00ed Backend Developer ho\u1eb7c Junior AI Engineer. N\u1ebfu c\u1ea7n tuy\u1ec3n g\u1ea5p, c\u00f3 th\u1ec3 c\u00e2n nh\u1eafc ph\u1ecfng v\u1ea5n \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 ti\u1ec1m n\u0103ng ph\u00e1t tri\u1ec3n, nh\u01b0ng kh\u00f4ng \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng c\u1ea5p cao."}', 'new', NULL, NULL, '2026-09-27 09:08:37.605039+07', '2026-09-27 09:08:41.114099+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('6a6af468-4400-4988-958a-fa07e26c7eef', '59811686-ce42-46ce-9954-684635269880', 'b83f72eb-0f7b-43f8-9b5d-ee720a04e725', 82.5, '{"overall_score": 82.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 90.0, "explanation": "\u1ee8ng vi\u00ean th\u00e0nh th\u1ea1o Python v\u00e0 c\u00f3 kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1edbi Gemini AI. Vi\u1ec7c s\u1eed d\u1ee5ng FastAPI v\u00e0 Docker cho th\u1ea5y kh\u1ea3 n\u0103ng l\u00e0m vi\u1ec7c t\u1ed1t v\u1edbi ki\u1ebfn tr\u00fac Microservices."}, {"name": "experience_years", "weight": 0.3, "score": 75.0, "explanation": "\u1ee8ng vi\u00ean c\u00f3 4 n\u0103m kinh nghi\u1ec7m. M\u1eb7c d\u00f9 \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u k\u1ef9 thu\u1eadt, nh\u01b0ng v\u1ecb tr\u00ed ''Senior AI Architect'' th\u01b0\u1eddng \u0111\u00f2i h\u1ecfi t\u1eeb 5-7 n\u0103m kinh nghi\u1ec7m tr\u1edf l\u00ean \u0111\u1ec3 \u0111\u1ea3m nh\u1eadn vai tr\u00f2 thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng quy m\u00f4 l\u1edbn."}, {"name": "education", "weight": 0.15, "score": 95.0, "explanation": "B\u1eb1ng Th\u1ea1c s\u0129 Khoa h\u1ecdc M\u00e1y t\u00ednh t\u1eeb \u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa l\u00e0 n\u1ec1n t\u1ea3ng h\u1ecdc thu\u1eadt r\u1ea5t m\u1ea1nh, ph\u00f9 h\u1ee3p v\u1edbi y\u00eau c\u1ea7u chuy\u00ean s\u00e2u c\u1ee7a v\u1ecb tr\u00ed Architect."}, {"name": "domain_knowledge", "weight": 0.15, "score": 70.0, "explanation": "C\u00f3 kinh nghi\u1ec7m v\u1ec1 RAG (Retrieval-Augmented Generation), cho th\u1ea5y t\u01b0 duy v\u1ec1 h\u1ec7 th\u1ed1ng AI Enterprise. Tuy nhi\u00ean, CV ch\u01b0a l\u00e0m r\u00f5 kinh nghi\u1ec7m tri\u1ec3n khai h\u1ec7 th\u1ed1ng AI \u1edf quy m\u00f4 doanh nghi\u1ec7p l\u1edbn (Enterprise scale)."}], "strengths": ["N\u1ec1n t\u1ea3ng h\u1ecdc v\u1ea5n chuy\u00ean m\u00f4n cao (Th\u1ea1c s\u0129 KHMT).", "K\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt th\u1ef1c t\u1ebf s\u00e1t v\u1edbi y\u00eau c\u1ea7u (Python, Gemini API, FastAPI, Docker).", "C\u00f3 kinh nghi\u1ec7m tri\u1ec3n khai RAG, m\u1ed9t k\u1ef9 n\u0103ng quan tr\u1ecdng trong ki\u1ebfn tr\u00fac AI hi\u1ec7n \u0111\u1ea1i."], "gaps": ["Thi\u1ebfu th\u00f4ng tin c\u1ee5 th\u1ec3 v\u1ec1 kinh nghi\u1ec7m thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng (System Design) \u1edf quy m\u00f4 Enterprise.", "S\u1ed1 n\u0103m kinh nghi\u1ec7m th\u1ef1c t\u1ebf h\u01a1i th\u1ea5p so v\u1edbi k\u1ef3 v\u1ecdng c\u1ee7a m\u1ed9t v\u1ecb tr\u00ed Senior Architect.", "Ch\u01b0a th\u1ec3 hi\u1ec7n r\u00f5 kh\u1ea3 n\u0103ng l\u00e3nh \u0111\u1ea1o k\u1ef9 thu\u1eadt ho\u1eb7c qu\u1ea3n l\u00fd d\u1ef1 \u00e1n AI ph\u1ee9c t\u1ea1p."], "recommendation": "N\u00ean m\u1eddi ph\u1ecfng v\u1ea5n. \u1ee8ng vi\u00ean c\u00f3 ti\u1ec1m n\u0103ng k\u1ef9 thu\u1eadt r\u1ea5t t\u1ed1t. Trong bu\u1ed5i ph\u1ecfng v\u1ea5n, c\u1ea7n t\u1eadp trung khai th\u00e1c c\u00e1c d\u1ef1 \u00e1n th\u1ef1c t\u1ebf \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 kh\u1ea3 n\u0103ng t\u01b0 duy ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng (System Design) v\u00e0 kinh nghi\u1ec7m gi\u1ea3i quy\u1ebft c\u00e1c b\u00e0i to\u00e1n kh\u00f3 khi tri\u1ec3n khai AI \u1edf quy m\u00f4 doanh nghi\u1ec7p."}', 'interview_invited', NULL, NULL, '2026-09-27 09:08:29.805147+07', '2026-09-27 09:08:45.413363+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('287c0b46-54c8-4e45-9683-35b3e868a8e7', 'c7cac402-eb38-46c1-ab90-da470b45071e', '6ce35f1c-fe82-4337-a890-5222c7872fe5', 92.5, '{"overall_score": 92.5, "breakdown": [{"criterion": "K\u1ef9 n\u0103ng chuy\u00ean m\u00f4n", "weight": 0.4, "score": 94.5, "comment": "K\u1ef9 n\u0103ng \u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u c\u00f4ng vi\u1ec7c"}, {"criterion": "S\u1ed1 n\u0103m kinh nghi\u1ec7m", "weight": 0.3, "score": 91.5, "comment": "4.5 n\u0103m kinh nghi\u1ec7m th\u1ef1c chi\u1ebfn"}, {"criterion": "H\u1ecdc v\u1ea5n & B\u1eb1ng c\u1ea5p", "weight": 0.15, "score": 90.0, "comment": "\u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa H\u00e0 N\u1ed9i"}, {"criterion": "K\u1ef9 n\u0103ng m\u1ec1m & ph\u00f9 h\u1ee3p", "weight": 0.15, "score": 88.0, "comment": "\u0110\u00e1nh gi\u00e1 ph\u00f9 h\u1ee3p v\u0103n h\u00f3a doanh nghi\u1ec7p"}], "strengths": ["Th\u00e0nh th\u1ea1o FastAPI & LangChain", "Kinh nghi\u1ec7m t\u1ed1i \u01b0u RAG vector latency"], "gaps": ["Ch\u01b0a c\u00f3 nhi\u1ec1u kinh nghi\u1ec7m tri\u1ec3n khai Kubernetes"], "recommendation": "\u01afu ti\u00ean ph\u1ecfng v\u1ea5n chuy\u00ean m\u00f4n k\u1ef9 thu\u1eadt s\u00e2u."}', 'interview_invited', NULL, NULL, '2026-09-27 09:21:30.039328+07', '2026-09-27 09:21:30.03933+07') ON CONFLICT DO NOTHING;
