INSERT INTO public.applications VALUES ('d75e454c-e275-4d41-ab15-1d23104ff08a', 'c7cac402-eb38-46c1-ab90-da470b45071e', 'd766bd30-5424-4e86-ad09-06d28d0ad2ef', 72, '{"overall_score": 72.0, "breakdown": [{"criterion": "K\u1ef9 n\u0103ng chuy\u00ean m\u00f4n", "weight": 0.4, "score": 74.0, "comment": "K\u1ef9 n\u0103ng \u0111\u00e1p \u1ee9ng y\u00eau c\u1ea7u c\u00f4ng vi\u1ec7c"}, {"criterion": "S\u1ed1 n\u0103m kinh nghi\u1ec7m", "weight": 0.3, "score": 71.0, "comment": "2.0 n\u0103m kinh nghi\u1ec7m th\u1ef1c chi\u1ebfn"}, {"criterion": "H\u1ecdc v\u1ea5n & B\u1eb1ng c\u1ea5p", "weight": 0.15, "score": 90.0, "comment": "\u0110\u1ea1i h\u1ecdc B\u00e1ch Khoa"}, {"criterion": "K\u1ef9 n\u0103ng m\u1ec1m & ph\u00f9 h\u1ee3p", "weight": 0.15, "score": 88.0, "comment": "\u0110\u00e1nh gi\u00e1 ph\u00f9 h\u1ee3p v\u0103n h\u00f3a doanh nghi\u1ec7p"}], "strengths": ["Ph\u00e2n t\u00edch d\u1eef li\u1ec7u t\u1ed1t, to\u00e1n h\u1ecdc v\u1eefng"], "gaps": ["Thi\u1ebfu kinh nghi\u1ec7m Backend FastAPI v\u00e0 LLM API th\u1ef1c chi\u1ebfn"], "recommendation": "L\u01b0u tr\u1eef v\u00e0o Talent Pool ph\u1ee5c v\u1ee5 c\u00e1c d\u1ef1 \u00e1n Data Science trong t\u01b0\u01a1ng lai."}', 'talent_pool', NULL, NULL, '2026-09-27 09:21:30.05465+07', '2026-09-27 09:21:30.054652+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('4b9f60f7-13e0-433b-bcb2-3042b13dcb34', '4d4348a8-80b6-414b-b0d3-b15a9601fe8c', '8422b4ef-6a69-4e58-bcea-6519ccce89b7', 25.5, '{"overall_score": 25.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 10.0, "explanation": "\u1ee8ng vi\u00ean thi\u1ebfu ho\u00e0n to\u00e0n c\u00e1c k\u1ef9 n\u0103ng c\u1ed1t l\u00f5i c\u1ee7a v\u1ecb tr\u00ed DevOps (Kubernetes, Terraform, AWS/GCP, CI/CD pipelines, Linux chuy\u00ean s\u00e2u). K\u1ef9 n\u0103ng hi\u1ec7n t\u1ea1i t\u1eadp trung v\u00e0o Web Development (React, Spring Boot, Python) v\u00e0 Embedded."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "Y\u00eau c\u1ea7u t\u1ed1i thi\u1ec3u 4 n\u0103m kinh nghi\u1ec7m DevOps/SRE. \u1ee8ng vi\u00ean l\u00e0 sinh vi\u00ean m\u1edbi t\u1ed1t nghi\u1ec7p (Fresher), ch\u01b0a c\u00f3 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c th\u1ef1c t\u1ebf trong l\u0129nh v\u1ef1c h\u1ea1 t\u1ea7ng/DevOps."}, {"name": "education", "weight": 0.15, "score": 70.0, "explanation": "T\u1ed1t nghi\u1ec7p chuy\u00ean ng\u00e0nh C\u00f4ng ngh\u1ec7 th\u00f4ng tin - K\u1ef9 thu\u1eadt ph\u1ea7n m\u1ec1m t\u1ea1i \u0110\u1ea1i h\u1ecdc S\u00e0i G\u00f2n, cung c\u1ea5p n\u1ec1n t\u1ea3ng t\u01b0 duy l\u1eadp tr\u00ecnh t\u1ed1t."}, {"name": "soft_skills", "weight": 0.15, "score": 75.0, "explanation": "C\u00f3 k\u1ef9 n\u0103ng l\u00e0m vi\u1ec7c nh\u00f3m, ph\u00e2n t\u00edch y\u00eau c\u1ea7u v\u00e0 giao ti\u1ebfp ti\u1ebfng Anh (VSTEP 5.5) kh\u00e1 t\u1ed1t, ph\u00f9 h\u1ee3p v\u1edbi m\u00f4i tr\u01b0\u1eddng l\u00e0m vi\u1ec7c chuy\u00ean nghi\u1ec7p."}], "strengths": ["N\u1ec1n t\u1ea3ng l\u1eadp tr\u00ecnh \u0111a d\u1ea1ng (Python, Java, C/C++, JavaScript).", "C\u00f3 t\u01b0 duy t\u1ed1t v\u1ec1 thi\u1ebft k\u1ebf c\u01a1 s\u1edf d\u1eef li\u1ec7u (ERD) v\u00e0 ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng c\u01a1 b\u1ea3n.", "K\u1ef9 n\u0103ng gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 v\u00e0 l\u00e0m vi\u1ec7c nh\u00f3m th\u00f4ng qua c\u00e1c d\u1ef1 \u00e1n th\u1ef1c t\u1ebf.", "Kh\u1ea3 n\u0103ng giao ti\u1ebfp ti\u1ebfng Anh t\u1ed1t, h\u1ed7 tr\u1ee3 t\u1ed1t cho vi\u1ec7c \u0111\u1ecdc t\u00e0i li\u1ec7u k\u1ef9 thu\u1eadt."], "gaps": ["Thi\u1ebfu ho\u00e0n to\u00e0n kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1ec1 DevOps, Cloud Infrastructure (AWS/GCP).", "Kh\u00f4ng c\u00f3 kinh nghi\u1ec7m v\u1eadn h\u00e0nh Kubernetes, Docker ho\u1eb7c c\u00e1c c\u00f4ng c\u1ee5 IaC (Terraform).", "Ch\u01b0a c\u00f3 kinh nghi\u1ec7m thi\u1ebft l\u1eadp h\u1ec7 th\u1ed1ng gi\u00e1m s\u00e1t (Prometheus/Grafana) ho\u1eb7c CI/CD pipelines.", "\u0110\u1ecbnh h\u01b0\u1edbng ngh\u1ec1 nghi\u1ec7p hi\u1ec7n t\u1ea1i c\u1ee7a \u1ee9ng vi\u00ean l\u00e0 Embedded Software, kh\u00f4ng ph\u00f9 h\u1ee3p v\u1edbi l\u1ed9 tr\u00ecnh DevOps."], "recommendation": "KH\u00d4NG PH\u00d9 H\u1ee2P. \u1ee8ng vi\u00ean hi\u1ec7n t\u1ea1i l\u00e0 Fresher v\u1edbi \u0111\u1ecbnh h\u01b0\u1edbng ph\u00e1t tri\u1ec3n v\u1ec1 Embedded/Software Development, kh\u00f4ng \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c y\u00eau c\u1ea7u v\u1ec1 kinh nghi\u1ec7m (4 n\u0103m) v\u00e0 k\u1ef9 n\u0103ng chuy\u00ean m\u00f4n (DevOps/Cloud) cho v\u1ecb tr\u00ed Lead. Kh\u00f4ng n\u00ean m\u1eddi ph\u1ecfng v\u1ea5n cho v\u1ecb tr\u00ed n\u00e0y."}', 'new', NULL, NULL, '2026-09-27 09:40:02.99429+07', '2026-09-27 09:40:07.314674+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('85da2681-0dcc-4719-8984-5de28c9e03f2', '4d4348a8-80b6-414b-b0d3-b15a9601fe8c', 'd7cc0fb4-8af8-4cc9-bd28-1ae8f68b2127', 0, '{"overall_score": 0.0, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u v\u1ec1 k\u1ef9 n\u0103ng chuy\u00ean m\u00f4n (Docker, Kubernetes, Terraform, AWS, Linux, CI/CD) \u0111\u1ec3 \u0111\u00e1nh gi\u00e1."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 qu\u00e1 tr\u00ecnh l\u00e0m vi\u1ec7c ho\u1eb7c s\u1ed1 n\u0103m kinh nghi\u1ec7m trong CV."}, {"name": "education", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 b\u1eb1ng c\u1ea5p ho\u1eb7c ch\u1ee9ng ch\u1ec9 chuy\u00ean m\u00f4n."}, {"name": "soft_skills", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 c\u00e1c k\u1ef9 n\u0103ng m\u1ec1m ho\u1eb7c kh\u1ea3 n\u0103ng l\u00e3nh \u0111\u1ea1o."}], "strengths": ["Kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u \u0111\u1ec3 x\u00e1c \u0111\u1ecbnh \u0111i\u1ec3m m\u1ea1nh."], "gaps": ["Thi\u1ebfu ho\u00e0n to\u00e0n n\u1ed9i dung CV (H\u1ed3 s\u01a1 tr\u1ed1ng).", "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 kinh nghi\u1ec7m l\u00e0m vi\u1ec7c, k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt v\u00e0 h\u1ecdc v\u1ea5n."], "recommendation": "T\u1eeb ch\u1ed1i ph\u1ecfng v\u1ea5n (Reject). H\u1ed3 s\u01a1 hi\u1ec7n t\u1ea1i kh\u00f4ng c\u00f3 d\u1eef li\u1ec7u \u0111\u1ec3 \u0111\u00e1nh gi\u00e1. Vui l\u00f2ng y\u00eau c\u1ea7u \u1ee9ng vi\u00ean cung c\u1ea5p CV \u0111\u1ea7y \u0111\u1ee7 ho\u1eb7c c\u1eadp nh\u1eadt th\u00f4ng tin chi ti\u1ebft tr\u01b0\u1edbc khi ti\u1ebfn h\u00e0nh \u0111\u00e1nh gi\u00e1."}', 'new', NULL, NULL, '2026-09-27 10:05:49.540092+07', '2026-09-27 10:05:53.219027+07') ON CONFLICT DO NOTHING;
INSERT INTO public.applications VALUES ('7c648250-848c-4013-a172-44eb3b3daeda', '4d4348a8-80b6-414b-b0d3-b15a9601fe8c', '86632518-dc58-42dc-a10a-c70e9e370bd6', 22.5, '{"overall_score": 22.5, "breakdown": [{"name": "required_skills", "weight": 0.4, "score": 10.0, "explanation": "\u1ee8ng vi\u00ean ch\u1ec9 li\u1ec7t k\u00ea k\u1ef9 n\u0103ng Python v\u00e0 AI. Thi\u1ebfu ho\u00e0n to\u00e0n c\u00e1c k\u1ef9 n\u0103ng c\u1ed1t l\u00f5i b\u1eaft bu\u1ed9c nh\u01b0 AWS/GCP, Kubernetes, Docker, Terraform, Linux v\u00e0 CI/CD."}, {"name": "experience_years", "weight": 0.3, "score": 0.0, "explanation": "CV kh\u00f4ng cung c\u1ea5p th\u00f4ng tin v\u1ec1 l\u1ecbch s\u1eed l\u00e0m vi\u1ec7c ho\u1eb7c s\u1ed1 n\u0103m kinh nghi\u1ec7m trong l\u0129nh v\u1ef1c DevOps/SRE."}, {"name": "education", "weight": 0.15, "score": 50.0, "explanation": "Th\u00f4ng tin v\u1ec1 tr\u00ecnh \u0111\u1ed9 h\u1ecdc v\u1ea5n kh\u00f4ng \u0111\u01b0\u1ee3c \u0111\u1ec1 c\u1eadp trong d\u1eef li\u1ec7u tr\u00edch xu\u1ea5t."}, {"name": "soft_skills", "weight": 0.15, "score": 0.0, "explanation": "Kh\u00f4ng c\u00f3 th\u00f4ng tin v\u1ec1 k\u1ef9 n\u0103ng m\u1ec1m ho\u1eb7c kh\u1ea3 n\u0103ng l\u00e3nh \u0111\u1ea1o (Lead) trong CV."}], "strengths": ["C\u00f3 k\u1ef9 n\u0103ng v\u1ec1 Python (ng\u00f4n ng\u1eef h\u1eefu \u00edch cho t\u1ef1 \u0111\u1ed9ng h\u00f3a DevOps).", "C\u00f3 ki\u1ebfn th\u1ee9c v\u1ec1 l\u0129nh v\u1ef1c AI (c\u00f3 th\u1ec3 h\u1ed7 tr\u1ee3 trong c\u00e1c d\u1ef1 \u00e1n MLOps n\u1ebfu c\u00f3)."], "gaps": ["Thi\u1ebfu ho\u00e0n to\u00e0n kinh nghi\u1ec7m th\u1ef1c t\u1ebf v\u1ec1 DevOps/SRE (y\u00eau c\u1ea7u t\u1ed1i thi\u1ec3u 4 n\u0103m).", "Thi\u1ebfu c\u00e1c k\u1ef9 n\u0103ng k\u1ef9 thu\u1eadt n\u1ec1n t\u1ea3ng: AWS/GCP, Kubernetes, Docker, Terraform, CI/CD.", "Thi\u1ebfu th\u00f4ng tin v\u1ec1 qu\u00e1 tr\u00ecnh l\u00e0m vi\u1ec7c v\u00e0 c\u00e1c d\u1ef1 \u00e1n \u0111\u00e3 th\u1ef1c hi\u1ec7n.", "Thi\u1ebfu b\u1eb1ng ch\u1ee9ng v\u1ec1 n\u0103ng l\u1ef1c l\u00e3nh \u0111\u1ea1o (Lead role)."], "recommendation": "KH\u00d4NG PH\u1eceNG V\u1ea4N. H\u1ed3 s\u01a1 \u1ee9ng vi\u00ean kh\u00f4ng \u0111\u00e1p \u1ee9ng \u0111\u01b0\u1ee3c c\u00e1c y\u00eau c\u1ea7u k\u1ef9 thu\u1eadt c\u01a1 b\u1ea3n c\u1ee7a v\u1ecb tr\u00ed DevOps & Cloud Infrastructure Lead. \u1ee8ng vi\u00ean n\u00e0y c\u00f3 v\u1ebb ph\u00f9 h\u1ee3p v\u1edbi c\u00e1c v\u1ecb tr\u00ed li\u00ean quan \u0111\u1ebfn Data/AI h\u01a1n l\u00e0 h\u1ea1 t\u1ea7ng h\u1ec7 th\u1ed1ng."}', 'new', NULL, NULL, '2026-09-27 10:05:53.419371+07', '2026-09-27 10:05:56.349253+07') ON CONFLICT DO NOTHING;


