INSERT INTO public.interview_evaluations VALUES ('57089382-7ad4-4843-8e9e-2bc569e98aa8', '8a5f0239-9239-4bf6-ac6f-34792dbc4951', 'da6328bb-6f21-4c46-a47b-2ba27bd13d88', '10f45483-a5da-4f91-b11b-c6145611b2a6', 8.5, '[{"criterion": "K\u1ef9 n\u0103ng chuy\u00ean m\u00f4n Python", "score": 9.0, "comment": "Th\u00e0nh th\u1ea1o async/await v\u00e0 ORM"}, {"criterion": "T\u01b0 duy gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1", "score": 8.0, "comment": "Ph\u00e2n t\u00edch b\u00e0i to\u00e1n r\u00f5 r\u00e0ng"}]', 'Ứng viên rất triển vọng, khuyên nên gửi Offer.', NULL, 'yes', '[]', NULL, NULL, '[]', '[]', '[]', NULL, '2026-09-26 21:49:26.920273+07', '2026-09-26 21:49:26.931315+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interview_evaluations VALUES ('c882447b-0e75-4a98-8f18-ca39d3dcd7e4', '5314a1e0-8223-4bb0-ac92-6f71ca4695c5', '6a6af468-4400-4988-958a-fa07e26c7eef', '2dbe45dd-0492-45f8-a28d-223e72ac5031', NULL, '[]', NULL, '/storage/interviews/5314a1e0-8223-4bb0-ac92-6f71ca4695c5_interview_record.mp3', 'yes', '[{"speaker": "Interviewer (HR)", "start_time": 0.0, "end_time": 15.5, "text": "Ch\u00e0o b\u1ea1n, c\u1ea3m \u01a1n b\u1ea1n \u0111\u00e3 tham gia bu\u1ed5i ph\u1ecfng v\u1ea5n h\u00f4m nay. B\u1ea1n c\u00f3 th\u1ec3 gi\u1edbi thi\u1ec7u ng\u1eafn g\u1ecdn v\u1ec1 kinh nghi\u1ec7m v\u1edbi FastAPI v\u00e0 h\u1ec7 th\u1ed1ng ph\u00e2n t\u00e1n?"}, {"speaker": "Candidate", "start_time": 16.0, "end_time": 68.2, "text": "D\u1ea1 v\u00e2ng ch\u00e0o anh/ch\u1ecb. Em c\u00f3 h\u01a1n 3 n\u0103m l\u00e0m vi\u1ec7c v\u1edbi Python v\u00e0 2 n\u0103m chuy\u00ean s\u00e2u v\u1ec1 FastAPI. \u1ede d\u1ef1 \u00e1n g\u1ea7n nh\u1ea5t, em thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng x\u1eed l\u00fd tin nh\u1eafn v\u00e0 ph\u00e2n t\u00edch d\u1eef li\u1ec7u \u1ee9ng vi\u00ean b\u1eb1ng Celery worker v\u00e0 Redis queue..."}, {"speaker": "Interviewer (Tech Lead)", "start_time": 69.0, "end_time": 92.0, "text": "R\u1ea5t t\u1ed1t. V\u1eady khi g\u1eb7p hi\u1ec7n t\u01b0\u1ee3ng database lock ho\u1eb7c spike t\u1ea3i b\u1ea5t ng\u1edd tr\u00ean PostgreSQL, b\u1ea1n \u0111\u00e3 \u00e1p d\u1ee5ng nh\u1eefng chi\u1ebfn l\u01b0\u1ee3c t\u1ed1i \u01b0u n\u00e0o?"}, {"speaker": "Candidate", "start_time": 93.0, "end_time": 154.0, "text": "Em \u0111\u00e3 c\u1ea5u h\u00ecnh connection pool v\u1edbi PgBouncer, \u0111\u00e1nh ch\u1ec9 m\u1ee5c partial index tr\u00ean c\u00e1c c\u1ed9t tr\u1ea1ng th\u00e1i truy v\u1ea5n th\u01b0\u1eddng xuy\u00ean v\u00e0 s\u1eed d\u1ee5ng Redis \u0111\u1ec3 cache k\u1ebft qu\u1ea3 truy v\u1ea5n \u0111\u1ecdc nhi\u1ec1u."}]', 8.4, 'Ứng viên trả lời mạch lạc, thể hiện sự am hiểu chắc chắn về FastAPI và PostgreSQL. Phản ứng nhanh trước các câu hỏi tình huống hệ thống.', '[{"criterion": "Ki\u1ebfn th\u1ee9c chuy\u00ean m\u00f4n", "score": 8.5, "evidence_quote": "\u1ede ph\u00fat 12:40, \u1ee9ng vi\u00ean gi\u1ea3i th\u00edch chi ti\u1ebft c\u01a1 ch\u1ebf ph\u00e2n trang cursor-based v\u00e0 caching Redis \u0111\u1ec3 gi\u1ea3m 70% t\u1ea3i DB.", "comment": "N\u1eafm r\u1ea5t ch\u1eafc c\u01a1 ch\u1ebf backend v\u00e0 h\u1ec7 th\u1ed1ng ph\u00e2n t\u00e1n."}, {"criterion": "K\u1ef9 n\u0103ng giao ti\u1ebfp & Di\u1ec5n \u0111\u1ea1t", "score": 8.2, "evidence_quote": "Tr\u00ecnh b\u00e0y c\u00f3 c\u1ea5u tr\u00fac STAR, gi\u1ecdng \u0111i\u1ec7u t\u1ef1 tin, l\u1eafng nghe k\u1ef9 c\u00e2u h\u1ecfi c\u1ee7a interviewer.", "comment": "Giao ti\u1ebfp t\u1ed1t, truy\u1ec1n \u0111\u1ea1t th\u00f4ng \u0111i\u1ec7p r\u00f5 r\u00e0ng."}, {"criterion": "Ph\u00f9 h\u1ee3p v\u0103n h\u00f3a", "score": 8.5, "evidence_quote": "Chia s\u1ebb quan \u0111i\u1ec3m t\u00edch c\u1ef1c khi nh\u1eadn feedback ph\u1ea3n bi\u1ec7n t\u1eeb \u0111\u1ed3ng nghi\u1ec7p.", "comment": "Th\u00e1i \u0111\u1ed9 h\u1ecdc h\u1ecfi v\u00e0 c\u1ea7u ti\u1ebfn cao."}]', '["T\u01b0 duy ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng b\u00e0i b\u1ea3n", "Kinh nghi\u1ec7m th\u1ef1c ti\u1ec5n gi\u1ea3i quy\u1ebft b\u00e0i to\u00e1n t\u1ea3i", "Th\u00e1i \u0111\u1ed9 chuy\u00ean nghi\u1ec7p, c\u1edfi m\u1edf"]', '["C\u1ea7n trau d\u1ed3i th\u00eam v\u1ec1 c\u00e1c m\u00f4 h\u00ecnh embedding vector v\u00e0 RAG pipelines"]', 'Đề xuất: Đạt (Pass) - Chuyển sang vòng thảo luận Offer với HR', '2026-09-27 09:08:45.455358+07', '2026-09-27 09:08:51.346437+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interview_evaluations VALUES ('c0bd09f2-9946-49b0-83cd-a73b82705e22', '7f790930-c680-4dde-8b8b-b61dc7b67482', '38cbe2f1-1f4e-4c4a-9e06-446d09688218', 'a6762851-2578-4266-a707-b35ac3b53b35', 8.8, '[{"criterion": "Ki\u1ebfn th\u1ee9c Kubernetes & Cloud", "score": 9.0, "comment": "N\u1eafm r\u1ea5t ch\u1eafc ki\u1ebfn tr\u00fac cluster v\u00e0 qu\u1ea3n l\u00fd t\u00e0i nguy\u00ean"}, {"criterion": "Kinh nghi\u1ec7m CI/CD", "score": 8.5, "comment": "X\u00e2y d\u1ef1ng pipeline t\u1ef1 \u0111\u1ed9ng h\u00f3a t\u1ed1t"}, {"criterion": "Kh\u1ea3 n\u0103ng x\u1eed l\u00fd s\u1ef1 c\u1ed1", "score": 9.0, "comment": "T\u01b0 duy logic m\u1ea1ch l\u1ea1c, ph\u01b0\u01a1ng ph\u00e1p debug b\u00e0i b\u1ea3n"}, {"criterion": "Giao ti\u1ebfp & L\u00e0m vi\u1ec7c nh\u00f3m", "score": 8.5, "comment": "Tr\u00ecnh b\u00e0y r\u00f5 r\u00e0ng, th\u00e1i \u0111\u1ed9 c\u1ea7u ti\u1ebfn"}]', 'Ứng viên trả lời rất lưu loát các câu hỏi tình huống thực tế về hạ tầng AWS và Kubernetes.', NULL, 'yes', '[{"speaker": "Interviewer (HR)", "start_time": 0.0, "end_time": 12.0, "text": "Ch\u00e0o anh Huy, c\u1ea3m \u01a1n anh \u0111\u00e3 tham gia bu\u1ed5i ph\u1ecfng v\u1ea5n v\u1ecb tr\u00ed DevOps Lead h\u00f4m nay."}, {"speaker": "Candidate", "start_time": 13.0, "end_time": 45.0, "text": "Ch\u00e0o anh, t\u00f4i c\u00f3 4 n\u0103m kinh nghi\u1ec7m qu\u1ea3n tr\u1ecb h\u1ea1 t\u1ea7ng \u0111\u00e1m m\u00e2y AWS v\u00e0 \u0111i\u1ec1u ph\u1ed1i container v\u1edbi Kubernetes."}, {"speaker": "Interviewer (Tech Lead)", "start_time": 46.0, "end_time": 68.0, "text": "Anh c\u00f3 th\u1ec3 gi\u1ea3i th\u00edch c\u00e1ch c\u1ea5u h\u00ecnh HPA v\u00e0 t\u1ed1i \u01b0u chi ph\u00ed h\u1ea1 t\u1ea7ng tr\u00ean EKS?"}, {"speaker": "Candidate", "start_time": 69.0, "end_time": 120.0, "text": "T\u00f4i k\u1ebft h\u1ee3p Karpenter \u0111\u1ec3 autoscaling node linh ho\u1ea1t d\u1ef1a tr\u00ean Spot Instances, k\u00e8m theo HPA d\u1ef1a tr\u00ean custom metrics t\u1eeb Prometheus."}]', 8.9, 'Ứng viên thể hiện hiểu biết sâu sắc về kiến trúc đám mây, tối ưu hóa chi phí với Karpenter và Spot instances trên Kubernetes.', '[{"criterion": "Technical Expertise", "score": 9.0}, {"criterion": "Problem Solving", "score": 8.8}, {"criterion": "System Reliability", "score": 9.0}]', '["Ki\u1ebfn th\u1ee9c chuy\u00ean s\u00e2u v\u1ec1 Karpenter & Kubernetes", "T\u01b0 duy t\u1ed1i \u01b0u chi ph\u00ed th\u1ef1c t\u1ebf"]', '["C\u1ea7n c\u1ee7ng c\u1ed1 th\u00eam v\u1ec1 b\u1ea3o m\u1eadt m\u1ea1ng n\u00e2ng cao (eBPF)"]', 'Pass', '2026-09-27 09:21:30.076927+07', '2026-09-27 09:21:30.076929+07') ON CONFLICT DO NOTHING;


