INSERT INTO public.interviews VALUES ('8a5f0239-9239-4bf6-ac6f-34792dbc4951', 'da6328bb-6f21-4c46-a47b-2ba27bd13d88', '5ccaa945-e8dd-46fd-b4de-3296d7be6ae4', '10f45483-a5da-4f91-b11b-c6145611b2a6', 'Phỏng vấn Kỹ thuật Vòng 1', 1, '2026-10-01 21:00:00+07', 45, 'online', 'https://meet.google.com/rec-202610011400', 'https://meet.google.com/abc-xyz-123', 'pending', false, false, '[]', '2026-09-26 21:49:08.191599+07', '2026-09-26 21:49:08.191603+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interviews VALUES ('e1f29811-3e04-4efa-9ba2-cb35d279f410', '8a7d3119-cef8-441a-a594-d4af0c8be3af', '465e795b-d3f5-4150-b402-cf0128cade13', '1ca475a5-b341-4a97-8147-d119456fdc92', 'Phỏng vấn Kỹ thuật Chuyên sâu AI', 1, '2026-09-29 09:06:53+07', 60, 'online', 'https://meet.google.com/rec-202609290206', NULL, 'pending', false, false, '[{"category": "K\u1ef9 thu\u1eadt", "question": "Trong d\u1ef1 \u00e1n RAG g\u1ea7n nh\u1ea5t, b\u1ea1n \u0111\u00e3 x\u1eed l\u00fd b\u00e0i to\u00e1n ''hallucination'' (\u1ea3o gi\u00e1c) c\u1ee7a m\u00f4 h\u00ecnh Gemini nh\u01b0 th\u1ebf n\u00e0o khi truy v\u1ea5n c\u00e1c t\u00e0i li\u1ec7u c\u00f3 \u0111\u1ed9 nhi\u1ec5u cao?", "rationale": "Ki\u1ec3m tra kh\u1ea3 n\u0103ng th\u1ef1c chi\u1ebfn v\u1edbi Gemini API v\u00e0 hi\u1ec3u bi\u1ebft s\u00e2u v\u1ec1 ki\u1ebfn tr\u00fac RAG thay v\u00ec ch\u1ec9 s\u1eed d\u1ee5ng th\u01b0 vi\u1ec7n c\u00f3 s\u1eb5n.", "expected_answer_points": [], "difficulty": "Hard"}, {"category": "Gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1", "question": "H\u00e3y m\u00f4 t\u1ea3 m\u1ed9t l\u1ea7n b\u1ea1n ph\u1ea3i thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng Microservices cho m\u1ed9t \u1ee9ng d\u1ee5ng AI c\u00f3 l\u01b0u l\u01b0\u1ee3ng truy c\u1eadp cao. B\u1ea1n \u0111\u00e3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 \u0111\u1ed9 tr\u1ec5 (latency) khi g\u1ecdi API Gemini nh\u01b0 th\u1ebf n\u00e0o?", "rationale": "V\u1ecb tr\u00ed Senior AI Architect c\u1ea7n t\u01b0 duy v\u1ec1 h\u1ec7 th\u1ed1ng (System Design) ch\u1ee9 kh\u00f4ng ch\u1ec9 l\u00e0 code \u0111\u01a1n l\u1ebb.", "expected_answer_points": [], "difficulty": "Hard"}, {"category": "Gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1", "question": "V\u1edbi 4 n\u0103m kinh nghi\u1ec7m, b\u1ea1n \u0111\u00e3 bao gi\u1edd g\u1eb7p t\u00ecnh hu\u1ed1ng ph\u1ea3i thay \u0111\u1ed5i ki\u1ebfn tr\u00fac h\u1ec7 th\u1ed1ng t\u1eeb Monolith sang Microservices ho\u1eb7c ng\u01b0\u1ee3c l\u1ea1i ch\u01b0a? T\u1ea1i sao?", "rationale": "\u0110\u00e1nh gi\u00e1 t\u01b0 duy ki\u1ebfn tr\u00fac v\u00e0 kh\u1ea3 n\u0103ng \u0111\u00e1nh gi\u00e1 trade-off (\u0111\u00e1nh \u0111\u1ed5i) trong k\u1ef9 thu\u1eadt.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "K\u1ef9 thu\u1eadt", "question": "Khi tri\u1ec3n khai c\u00e1c model AI tr\u00ean Docker, b\u1ea1n th\u01b0\u1eddng t\u1ed1i \u01b0u h\u00f3a image size v\u00e0 th\u1eddi gian kh\u1edfi \u0111\u1ed9ng (cold start) nh\u01b0 th\u1ebf n\u00e0o?", "rationale": "Ki\u1ec3m tra k\u1ef9 n\u0103ng DevOps/Infrastructure c\u01a1 b\u1ea3n c\u1ee7a m\u1ed9t AI Architect.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "V\u0103n h\u00f3a", "question": "N\u1ebfu m\u1ed9t th\u00e0nh vi\u00ean trong team kh\u00f4ng \u0111\u1ed3ng \u00fd v\u1edbi c\u00e1ch ti\u1ebfp c\u1eadn k\u1ef9 thu\u1eadt c\u1ee7a b\u1ea1n v\u1ec1 vi\u1ec7c ch\u1ecdn framework ho\u1eb7c ki\u1ebfn tr\u00fac AI, b\u1ea1n s\u1ebd x\u1eed l\u00fd t\u00ecnh hu\u1ed1ng \u0111\u00f3 ra sao?", "rationale": "\u0110\u00e1nh gi\u00e1 k\u1ef9 n\u0103ng l\u00e3nh \u0111\u1ea1o, giao ti\u1ebfp v\u00e0 kh\u1ea3 n\u0103ng l\u00e0m vi\u1ec7c nh\u00f3m \u1edf c\u1ea5p \u0111\u1ed9 Senior.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "K\u1ef9 thu\u1eadt", "question": "Trong b\u1ed1i c\u1ea3nh Gemini API li\u00ean t\u1ee5c c\u1eadp nh\u1eadt c\u00e1c phi\u00ean b\u1ea3n m\u1edbi, l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 b\u1ea1n \u0111\u1ea3m b\u1ea3o h\u1ec7 th\u1ed1ng c\u1ee7a m\u00ecnh kh\u00f4ng b\u1ecb ''break'' khi c\u00f3 thay \u0111\u1ed5i t\u1eeb ph\u00eda nh\u00e0 cung c\u1ea5p?", "rationale": "Ki\u1ec3m tra t\u01b0 duy v\u1ec1 t\u00ednh b\u1ec1n v\u1eefng (Robustness) v\u00e0 kh\u1ea3 n\u0103ng qu\u1ea3n l\u00fd r\u1ee7i ro c\u1ee7a h\u1ec7 th\u1ed1ng.", "expected_answer_points": [], "difficulty": "Easy"}]', '2026-09-27 09:06:58.342632+07', '2026-09-27 09:06:58.342637+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interviews VALUES ('5314a1e0-8223-4bb0-ac92-6f71ca4695c5', '6a6af468-4400-4988-958a-fa07e26c7eef', '29a3b170-5524-4f94-83f1-3d3b17359375', '2dbe45dd-0492-45f8-a28d-223e72ac5031', 'Phỏng vấn Kỹ thuật Chuyên sâu AI', 1, '2026-09-29 09:08:41+07', 60, 'online', 'https://meet.google.com/rec-202609290208', NULL, 'pending', false, false, '[{"category": "K\u1ef9 thu\u1eadt", "question": "Trong d\u1ef1 \u00e1n RAG g\u1ea7n nh\u1ea5t, b\u1ea1n \u0111\u00e3 x\u1eed l\u00fd b\u00e0i to\u00e1n ''hallucination'' (\u1ea3o t\u01b0\u1edfng) c\u1ee7a m\u00f4 h\u00ecnh Gemini nh\u01b0 th\u1ebf n\u00e0o khi truy v\u1ea5n d\u1eef li\u1ec7u \u0111\u1eb7c th\u00f9 c\u1ee7a doanh nghi\u1ec7p?", "rationale": "Ki\u1ec3m tra kh\u1ea3 n\u0103ng th\u1ef1c chi\u1ebfn v\u1edbi Gemini API v\u00e0 hi\u1ec3u bi\u1ebft s\u00e2u v\u1ec1 ki\u1ebfn tr\u00fac RAG thay v\u00ec ch\u1ec9 s\u1eed d\u1ee5ng c\u00e1c th\u01b0 vi\u1ec7n c\u00f3 s\u1eb5n.", "expected_answer_points": [], "difficulty": "Hard"}, {"category": "Gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1", "question": "H\u00e3y m\u00f4 t\u1ea3 m\u1ed9t t\u00ecnh hu\u1ed1ng b\u1ea1n ph\u1ea3i thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng Microservices s\u1eed d\u1ee5ng Python \u0111\u1ec3 x\u1eed l\u00fd l\u01b0u l\u01b0\u1ee3ng truy c\u1eadp l\u1edbn cho c\u00e1c t\u00e1c v\u1ee5 AI. B\u1ea1n \u0111\u00e3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 ngh\u1ebdn c\u1ed5 chai (bottleneck) nh\u01b0 th\u1ebf n\u00e0o?", "rationale": "V\u1ecb tr\u00ed Senior AI Architect c\u1ea7n t\u01b0 duy h\u1ec7 th\u1ed1ng (System Design) ch\u1ee9 kh\u00f4ng ch\u1ec9 l\u00e0 vi\u1ebft code.", "expected_answer_points": [], "difficulty": "Hard"}, {"category": "K\u1ef9 thu\u1eadt", "question": "Khi t\u00edch h\u1ee3p Gemini API v\u00e0o h\u1ec7 th\u1ed1ng Microservices, b\u1ea1n l\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 \u0111\u1ea3m b\u1ea3o t\u00ednh s\u1eb5n s\u00e0ng (availability) v\u00e0 qu\u1ea3n l\u00fd chi ph\u00ed (cost optimization) khi s\u1ed1 l\u01b0\u1ee3ng request t\u0103ng \u0111\u1ed9t bi\u1ebfn?", "rationale": "\u0110\u00e1nh gi\u00e1 t\u01b0 duy t\u1ed1i \u01b0u chi ph\u00ed v\u00e0 \u0111\u1ed9 \u1ed5n \u0111\u1ecbnh c\u1ee7a h\u1ec7 th\u1ed1ng trong m\u00f4i tr\u01b0\u1eddng production.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "V\u0103n h\u00f3a", "question": "K\u1ec3 v\u1ec1 m\u1ed9t l\u1ea7n b\u1ea1n ph\u1ea3i thuy\u1ebft ph\u1ee5c team ho\u1eb7c c\u1ea5p tr\u00ean thay \u0111\u1ed5i m\u1ed9t ki\u1ebfn tr\u00fac k\u1ef9 thu\u1eadt m\u00e0 b\u1ea1n cho l\u00e0 kh\u00f4ng hi\u1ec7u qu\u1ea3. B\u1ea1n \u0111\u00e3 l\u00e0m th\u1ebf n\u00e0o?", "rationale": "\u0110\u00e1nh gi\u00e1 k\u1ef9 n\u0103ng giao ti\u1ebfp, kh\u1ea3 n\u0103ng l\u00e3nh \u0111\u1ea1o k\u1ef9 thu\u1eadt v\u00e0 t\u01b0 duy ph\u1ea3n bi\u1ec7n.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "Gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1", "question": "V\u1edbi kinh nghi\u1ec7m 4 n\u0103m, n\u1ebfu ph\u1ea3i ch\u1ecdn gi\u1eefa vi\u1ec7c t\u1ef1 x\u00e2y d\u1ef1ng (build) m\u1ed9t module AI hay s\u1eed d\u1ee5ng d\u1ecbch v\u1ee5 c\u00f3 s\u1eb5n (buy/API), b\u1ea1n d\u1ef1a tr\u00ean nh\u1eefng ti\u00eau ch\u00ed n\u00e0o \u0111\u1ec3 ra quy\u1ebft \u0111\u1ecbnh?", "rationale": "Ki\u1ec3m tra t\u01b0 duy chi\u1ebfn l\u01b0\u1ee3c c\u1ee7a m\u1ed9t Architect.", "expected_answer_points": [], "difficulty": "Medium"}, {"category": "K\u1ef9 thu\u1eadt", "question": "H\u00e3y gi\u1ea3i th\u00edch c\u00e1ch b\u1ea1n qu\u1ea3n l\u00fd v\u00f2ng \u0111\u1eddi c\u1ee7a m\u1ed9t Docker container ch\u1ee9a \u1ee9ng d\u1ee5ng AI n\u1eb7ng v\u1ec1 t\u00e0i nguy\u00ean (GPU/RAM) trong m\u00f4i tr\u01b0\u1eddng CI/CD.", "rationale": "X\u00e1c nh\u1eadn k\u1ef9 n\u0103ng n\u1ec1n t\u1ea3ng v\u1ec1 DevOps/Infrastructure m\u00e0 m\u1ed9t Senior AI Architect b\u1eaft bu\u1ed9c ph\u1ea3i c\u00f3.", "expected_answer_points": [], "difficulty": "Easy"}]', '2026-09-27 09:08:45.415642+07', '2026-09-27 09:08:45.415646+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interviews VALUES ('377a6e73-7d2f-4201-b791-1ebd402864bd', '287c0b46-54c8-4e45-9683-35b3e868a8e7', '712f420a-6fe6-4b48-a996-e525d81acc37', 'a6762851-2578-4266-a707-b35ac3b53b35', 'Phỏng vấn Chuyên môn Kỹ thuật AI - Nguyễn Văn An', 1, '2026-09-29 12:21:30.061341+07', 60, 'online', 'https://meet.google.com/rec-demo-an2026', NULL, 'confirmed', false, false, '[{"question": "B\u1ea1n h\u00e3y m\u00f4 t\u1ea3 m\u1ed9t th\u1eed th\u00e1ch l\u1edbn nh\u1ea5t khi thi\u1ebft k\u1ebf pipeline RAG v\u00e0 c\u00e1ch b\u1ea1n gi\u1ea3i quy\u1ebft b\u00e0i to\u00e1n context length?", "category": "technical", "rationale": "Ki\u1ec3m tra ki\u1ebfn th\u1ee9c chuy\u00ean s\u00e2u v\u1ec1 LLM retrieval", "expected_answer_points": ["Chunking strategy", "Reranking", "Vector similarity metric"]}, {"question": "Khi x\u1eed l\u00fd b\u1ea5t \u0111\u1ed3ng b\u1ed9 h\u00e0ng \u0111\u1ee3i Celery b\u1ecb t\u1eafc ngh\u1ebdn, b\u1ea1n debug v\u00e0 kh\u00f4i ph\u1ee5c h\u1ec7 th\u1ed1ng nh\u01b0 th\u1ebf n\u00e0o?", "category": "problem_solving", "rationale": "\u0110\u00e1nh gi\u00e1 kh\u1ea3 n\u0103ng x\u1eed l\u00fd s\u1ef1 c\u1ed1 production", "expected_answer_points": ["Dead letter queue", "Worker concurrency", "Prefetch multiplier"]}]', '2026-09-27 09:21:30.063323+07', '2026-09-27 09:21:30.063326+07') ON CONFLICT DO NOTHING;
INSERT INTO public.interviews VALUES ('7f790930-c680-4dde-8b8b-b61dc7b67482', '38cbe2f1-1f4e-4c4a-9e06-446d09688218', '712f420a-6fe6-4b48-a996-e525d81acc37', 'a6762851-2578-4266-a707-b35ac3b53b35', 'Phỏng vấn Hệ thống & DevOps - Đặng Quốc Huy', 1, '2026-09-26 09:21:30.062118+07', 45, 'online', 'https://meet.google.com/rec-demo-huy2026', NULL, 'confirmed', false, false, '[{"question": "Khi Kubernetes cluster x\u1ea3y ra hi\u1ec7n t\u01b0\u1ee3ng OOMKilled tr\u00ean worker pods, b\u1ea1n \u0111i\u1ec1u tra nguy\u00ean nh\u00e2n theo nh\u1eefng b\u01b0\u1edbc n\u00e0o?", "category": "technical", "rationale": "K\u1ef9 n\u0103ng v\u1eadn h\u00e0nh Kubernetes chuy\u00ean s\u00e2u", "expected_answer_points": ["kubectl describe pod", "Resource limits and requests", "cgroups memory leak"]}, {"question": "L\u00e0m th\u1ebf n\u00e0o \u0111\u1ec3 thi\u1ebft l\u1eadp quy tr\u00ecnh Zero-downtime deployment cho microservices?", "category": "architecture", "rationale": "\u0110\u00e1nh gi\u00e1 thi\u1ebft k\u1ebf h\u1ec7 th\u1ed1ng c\u00f3 t\u00ednh s\u1eb5n s\u00e0ng cao", "expected_answer_points": ["Rolling update", "Readiness probes", "Canary release"]}]', '2026-09-27 09:21:30.063333+07', '2026-09-27 09:21:30.063334+07') ON CONFLICT DO NOTHING;


